  /// Default empty.
  const ::flatbuffers::String *TIME_SYSTEM() const {
    return GetPointer<const ::flatbuffers::String *>(VT_TIME_SYSTEM);
  }
  /// Time of clock, ISO 8601 on TIME_SYSTEM. Default empty.
  const ::flatbuffers::String *TOC() const {
    return GetPointer<const ::flatbuffers::String *>(VT_TOC);
  }
  /// Satellite clock bias, s.
  double CLOCK_BIAS() const {
    return GetField<double>(VT_CLOCK_BIAS, 0.0);
  }
  /// Satellite clock drift, s/s.
  double CLOCK_DRIFT() const {
    return GetField<double>(VT_CLOCK_DRIFT, 0.0);
  }
  /// Satellite clock drift rate, s/s^2.
  double CLOCK_DRIFT_RATE() const {
    return GetField<double>(VT_CLOCK_DRIFT_RATE, 0.0);
  }
  /// Transmission time of the message, seconds of the system week.
  double TRANSMISSION_TIME() const {
    return GetField<double>(VT_TRANSMISSION_TIME, 0.0);
  }
