inline ::flatbuffers::Offset<GNM> CreateGNM(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> SATELLITE_ID = 0,
    gnssConstellation CONSTELLATION = gnssConstellation::GPS,
    gnssNavMessageType MESSAGE_TYPE = gnssNavMessageType::UNSPECIFIED,
    ::flatbuffers::Offset<::flatbuffers::String> TIME_SYSTEM = 0,
    ::flatbuffers::Offset<::flatbuffers::String> TOC = 0,
    double CLOCK_BIAS = 0.0,
    double CLOCK_DRIFT = 0.0,
    double CLOCK_DRIFT_RATE = 0.0,
    double TRANSMISSION_TIME = 0.0,
    uint32_t HEALTH = 0,
    bool HAS_HEALTH = false,
    double ACCURACY = 0.0,
    int32_t ACCURACY_INDEX = 0,
    bool HAS_ACCURACY_INDEX = false,
    ::flatbuffers::Offset<::flatbuffers::Vector<double>> GROUP_DELAYS = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> GROUP_DELAY_NAMES = 0,
    ::flatbuffers::Offset<gnssKeplerianBroadcast> KEPLERIAN = 0,
    ::flatbuffers::Offset<gnssStateBroadcast> STATE = 0,
    uint32_t DATA_SOURCES = 0) {
  GNMBuilder builder_(_fbb);
  builder_.add_ACCURACY(ACCURACY);
  builder_.add_TRANSMISSION_TIME(TRANSMISSION_TIME);
  builder_.add_CLOCK_DRIFT_RATE(CLOCK_DRIFT_RATE);
  builder_.add_CLOCK_DRIFT(CLOCK_DRIFT);
  builder_.add_CLOCK_BIAS(CLOCK_BIAS);
  builder_.add_DATA_SOURCES(DATA_SOURCES);
  builder_.add_STATE(STATE);
  builder_.add_KEPLERIAN(KEPLERIAN);
  builder_.add_GROUP_DELAY_NAMES(GROUP_DELAY_NAMES);
  builder_.add_GROUP_DELAYS(GROUP_DELAYS);
  builder_.add_ACCURACY_INDEX(ACCURACY_INDEX);
  builder_.add_HEALTH(HEALTH);
  builder_.add_TOC(TOC);
  builder_.add_TIME_SYSTEM(TIME_SYSTEM);
  builder_.add_SATELLITE_ID(SATELLITE_ID);
  builder_.add_HAS_ACCURACY_INDEX(HAS_ACCURACY_INDEX);
  builder_.add_HAS_HEALTH(HAS_HEALTH);
  builder_.add_MESSAGE_TYPE(MESSAGE_TYPE);
  builder_.add_CONSTELLATION(CONSTELLATION);
  return builder_.Finish();
}

