inline const GNM *GetGNM(const void *buf) {
  return ::flatbuffers::GetRoot<GNM>(buf);
}

inline const GNM *GetSizePrefixedGNM(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<GNM>(buf);
}

inline const char *GNMIdentifier() {
  return "$GNM";
}

inline bool GNMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, GNMIdentifier());
}

inline bool SizePrefixedGNMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, GNMIdentifier(), true);
}

template <bool B = false>
inline bool VerifyGNMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<GNM>(GNMIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedGNMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<GNM>(GNMIdentifier());
}

inline void FinishGNMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<GNM> root) {
  fbb.Finish(root, GNMIdentifier());
}

inline void FinishSizePrefixedGNMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<GNM> root) {
  fbb.FinishSizePrefixed(root, GNMIdentifier());
}

inline std::unique_ptr<GNMT> UnPackGNM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<GNMT>(GetGNM(buf)->UnPack(res));
}

inline std::unique_ptr<GNMT> UnPackSizePrefixedGNM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<GNMT>(GetSizePrefixedGNM(buf)->UnPack(res));
}

